def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = int(data[0])
    # upper bound for x: x^3 = N + y^3, y>=1, so x <= ceil((N+1)^(1/3)) roughly
    # but y can be close to x; direct search x in [1, floor(cbrt(N))+2]
    def icbrt(v):
        if v <= 0:
            return 0
        # integer cube root
        r = int(v ** (1.0/3.0))
        while (r+1)**3 <= v:
            r += 1
        while r**3 > v:
            r -= 1
        return r

    limit = icbrt(N + 1) + 2
    # More precise: y <= x, x^3 - y^3 = N. We search x from icbrt(N) to icbrt(N)+... 
    # Easier: search y small? x = y + d. Use x range from icbrt(N) to icbrt(N + y^3).
    # Since y can be large, x can be larger. Use x up to icbrt(2*N) maybe.
    xmax = icbrt(2*N + 1) + 5
    for x in range(1, xmax+1):
        rem = x*x*x - N
        if rem < 1:
            continue
        y = icbrt(rem)
        # y must be positive and (y+1)^3 > rem
        for yy in (y, y+1):
            if yy >= 1 and x*x*x - yy*yy*yy == N:
                print(x, yy)
                return
    print(-1)

