                        new_pa = []
                        for x in pa:
                            if x == i:
                                new_pa.append(j)
                            elif x == j:
                                new_pa.append(i)
                            else:
                                new_pa.append(x)
                        new_pb = []
                        for x in pb:
                            if x == i:
                                new_pb.append(j)
                            elif x == j:
                                new_pb.append(i)
                            else:
                                new_pb.append(x)
                        # Since i is an a-position and j is a b-position, swap affects only those positions
                        new_pa = [j if x == i else x for x in pa]
                        new_pb = [i if x == j else x for x in pb]
