def dijkstra(N, adj, src):
    dist = [float('inf')] * (N + 1)
    dist[src] = 0
    # small graph: simple O(N^2) Dijkstra
    for _ in range(N):
        u = -1
        best = float('inf')
        for i in range(1, N + 1):
            if dist[i] < best:
                best = dist[i]
                u = i
        if u == -1 or best == float('inf'):
            break
        for v, w in adj[u]:
            nd = dist[u] + w
            if nd < dist[v]:
                dist[v] = nd
    return dist[N]

