import heapq

def main():
    input = sys.stdin.readline
    N, M, X = map(int, input().split())
    edges = []
    for _ in range(M):
        u, v = map(int, input().split())
        edges.append((u, v))

    # state id: (vertex, reversed?) where reversed 0=normal, 1=reversed
    # normal edges: u->v; reversed edges: v->u
    # Costs are nonnegative; X>0.
    INF = float('inf')
    dist = [[INF, INF] for _ in range(N + 1)]
    dist[1][0] = 0
    pq = [(0, 1, 0)]

    def rev_state(u, v, s):
        # If s==0, directed edge u->v. If s==1, edge v->u.
        if s == 0:
            return (u, v)
        else:
            return (v, u)

    while pq:
        d, v, s = heapq.heappop(pq)
        if d > dist[v][s]:
            continue
        # Reversal operation
        ns = 1 - s
        nd = d + X
        if nd < dist[v][ns]:
            dist[v][ns] = nd
            heapq.heappush(pq, (nd, v, ns))
        # Move operation
        for u, v_ in edges:
            if s == 0:
                if u == v:
                    to = v_
                else:
                    continue
            else:
                # reversed edge: u->v becomes v->u, so from v_ to u
                if v_ == v:
                    to = u
                else:
                    continue
            nd = d + 1
            if nd < dist[to][s]:
                dist[to][s] = nd
                heapq.heappush(pq, (nd, to, s))

    ans = min(dist[N][0], dist[N][1])
    print(ans)

