from collections import deque

def solve():
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    Q = int(data[idx]); idx += 1

    l = 1
    r = 2
    total = 0

    def neighbors(x):
        # ring neighbors 1..N
        a = x - 1 if x > 1 else N
        b = x + 1 if x < N else 1
        return (a, b)

    for _ in range(Q):
        H = data[idx]; T = int(data[idx+1]); idx += 2
        if H == 'L':
            start = l
            fixed = r
            forbidden = fixed
        else:
            start = r
            fixed = l
            forbidden = fixed

        # movable hand must reach T; T != fixed is guaranteed
        if start == T:
            dist = 0
        else:
            q = deque([start])
            dist_map = {start: 0}
            target = None
            while q:
                x = q.popleft()
                if x == T:
                    target = dist_map[x]
                    break
                for y in neighbors(x):
                    if y == forbidden:
                        continue
                    if y not in dist_map:
                        dist_map[y] = dist_map[x] + 1
                        q.append(y)
            target = dist_map.get(T, 0)
            dist = target

        total += dist
        if H == 'L':
            l = T
        else:
            r = T

    print(total)

